// Pedagogical diagnostic; not application implementation.
const { createCartridge } =
  await import('./src/handheld.js');
const prop = createCartridge('#666574', 'TEST', 'LOCAL');
const names = [];
prop.traverse(node => {
  if (node.isMesh) names.push(node.name || '(text plane)');
});
console.table(names);
console.assert(
  names.filter(n => n === 'Cartridge grip').length === 5
);

// Pedagogical diagnostic; root is an existing factory root.
const { Raycaster, Vector3 } = await import('three');
root.updateWorldMatrix(true, true);
const origin = root.localToWorld(new Vector3(0, .22, 4));
const direction = new Vector3(0, 0, -1)
  .transformDirection(root.matrixWorld);
const hit = new Raycaster(origin, direction)
  .intersectObject(root, true)[0];
if (!hit) throw new Error('No front surface');
console.log(hit.object.name);
console.log(root.worldToLocal(hit.point.clone()).z);

// Pedagogical geometry experiment.
const { roundedBox } = await import('./src/handheld.js');
const geometry = roundedBox(2, 1, .2, .12, .03);
geometry.computeBoundingBox();
const b = geometry.boundingBox;
console.table({
  minZ: b.min.z,
  maxZ: b.max.z,
  centered: Math.abs(b.min.z + b.max.z) < 1e-6
});
console.assert(b.max.z > .1);
console.assert(b.min.z < -.1);
geometry.dispose();

// Pedagogical envelope diagnostic.
const { loadBrand } = await import('./src/brand.js');
const { createHandheld } = await import('./src/handheld.js');
await loadBrand();
const specimen = createHandheld();
for (const name of ['Front shell',
  'Front face with speaker apertures']) {
  const mesh = specimen.root.getObjectByName(name);
  mesh.geometry.computeBoundingBox();
  const b = mesh.geometry.boundingBox;
  console.log(name,
    mesh.position.z + b.min.z,
    mesh.position.z + b.max.z);
}

// Pedagogical UV invariant check.
const { createLcdGeometries } =
  await import('./src/handheld.js');
for (const curved of [false, true]) {
  const { screen, recess } = createLcdGeometries(curved);
  const p = screen.getAttribute('position');
  const uv = screen.getAttribute('uv');
  const { width: w, height: h } = screen.userData.viewport;
  let error = 0;
  for (let i = 0; i < p.count; i++) {
    error = Math.max(error,
      Math.abs(uv.getX(i) - (p.getX(i) / w + .5)),
      Math.abs(uv.getY(i) - (p.getY(i) / h + .5)));
  }
  console.log({ curved, error });
  console.assert(error < 1e-6);
  screen.dispose(); recess.dispose();
}

// Pedagogical metadata check on an independent model.
const controls = model.controls;
console.assert(
  controls.get('up').mesh === controls.get('right').mesh
);
const a = controls.get('a').mesh.userData.motion;
console.log(a.restPosition.z, a.travel.toArray());
console.assert(Math.abs(a.travel.z + .075) < 1e-9);
console.assert(controls.get('up').anchor !==
  controls.get('right').anchor);

// Pedagogical fitting diagnostic.
const { Box3, Vector3 } = await import('three');
const { createCartridge } =
  await import('./src/handheld.js');
const prop = createCartridge('#666574', 'TEST', 'LOCAL');
prop.scale.set(1.9, 1.9, 1);
prop.updateWorldMatrix(true, true);
const size = new Box3().setFromObject(prop)
  .getSize(new Vector3());
console.log(size.toArray());
console.log('Width remaining:', 3.05 - size.x);
console.assert(size.x < 3.05);

// Pedagogical deterministic-painter check.
const { createWood } = await import('./src/handheld.js');
function hash(texture) {
  const c = texture.image;
  const bytes = c.getContext('2d')
    .getImageData(0, 0, c.width, c.height).data;
  let value = 2166136261;
  for (const byte of bytes) {
    value = Math.imul(value ^ byte, 16777619);
  }
  return value >>> 0;
}
const a = createWood(), b = createWood();
console.assert(hash(a) === hash(b));
console.log(a.repeat.toArray());
a.dispose(); b.dispose();

import * as THREE from 'three';
import { createDsHandheld } from './src/ds-handheld.js';

const ds = createDsHandheld();
ds.lid.rotation.x = THREE.MathUtils.degToRad(35);
ds.root.updateWorldMatrix(true, true);
console.assert(
  Math.abs(ds.lid.rotation.x - Math.PI * 35 / 180) < 1e-12
);

const held = new Set(['up', 'right']);
const x = +held.has('down') - +held.has('up');
const y = +held.has('right') - +held.has('left');
const n = Math.max(1, Math.hypot(x, y));
const target = { pitch: x * .16 / n, yaw: y * .16 / n };
console.assert(Math.abs(Math.hypot(
  target.pitch, target.yaw
) - .16) < 1e-12);
console.log(target);

const width = 4.5, height = 3.375;
console.assert(width / 256 === height / 192);
const uv = { x: .25, y: .75 };
const pixel = {
  x: Math.min(255, Math.floor(uv.x * 256)),
  y: Math.min(191, Math.floor((1 - uv.y) * 192))
};
console.log(pixel); // { x: 64, y: 48 }

function cardY(elapsed) {
  const f = Math.min(1, Math.max(0, elapsed) / 1800);
  const e = f * f * (3 - 2 * f);
  return 3.1 + (.44 - 3.1) * e;
}
console.assert(Math.abs(cardY(900) - 1.77) < 1e-12);
console.assert(Math.abs(cardY(1800) - .44) < 1e-12);

const w = 960, h = 720, fov = 40;
const size = { x: 9, y: 10, z: 3 };
const tangent = Math.tan(fov * Math.PI / 360);
const widthNeed = Math.max(12, size.x + 1.2) / (w / h);
const heightNeed = (size.y + .8) * h / (h - 90 - 120);
const distance = Math.max(widthNeed, heightNeed)
  / (2 * tangent) + size.z / 2;
console.log(distance);

import { createDeskLamp } from './src/lighting.js';
const lamp = createDeskLamp();
const body = lamp.root.children[0];
const legs = body.children.filter(
  item => item.name.startsWith('Ash tripod leg')
);
console.assert(legs.length === 3);
console.log(legs.map(item => item.name));
console.log(.30 * body.scale.y); // 17.647...

const target = .5;
const delta = .1;
const current = target * (1 - Math.exp(-18 * delta));
const primary = current * 12;
const spill = current ** .25 * .1;
console.assert(primary > 5 && primary < 5.02);
console.log({ current, primary, spill });

const { drawLcdCrt } = await import('./src/lcd-crt.js');
const canvas = document.createElement('canvas');
canvas.width = 720;
canvas.height = 480;
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#808080';
ctx.fillRect(0, 0, 720, 480);
ctx.globalAlpha = .7;
drawLcdCrt(ctx, 160);
console.assert(ctx.globalAlpha === .7);
document.body.append(canvas);

const rect = { left: 100, top: 50, width: 800, height: 600 };
const event = { clientX: 500, clientY: 200 };
const x = (event.clientX - rect.left) / rect.width * 2 - 1;
const y = -(event.clientY - rect.top) / rect.height * 2 + 1;
console.assert(x === 0 && y === .5);
const offset = [2, 0, -1];
const nextHit = [4, 5, 2];
console.log(nextHit.map((v, i) => v + offset[i]));
// [6, 5, 1]

function nextPaint(submitted, observed, moving) {
  const elapsed = Math.max(0, observed - submitted);
  const limit = moving ? 200 : 1000;
  const idle = elapsed > 100
    ? Math.min(limit, elapsed * 2) : 0;
  return observed + idle;
}
console.assert(nextPaint(1000, 1100, false) === 1100);
console.assert(nextPaint(1000, 1101, false) === 1303);
console.assert(nextPaint(1000, 2000, true) === 2200);

import { Box3, Vector3 } from 'three';
import { nearestDeskPosition } from './src/desk-clearance.js';
const box = (a, b) => new Box3(new Vector3(...a),
  new Vector3(...b));
const bounds = box([-1, 0, -.5], [2, 2, .5]);
const workspace = box([-10, 0, -10], [10, 10, 10]);
const obstacle = box([4, 0, 0], [6, 4, 2]);
const wanted = new Vector3(3, 1, 1);
const answer = nearestDeskPosition(
  bounds, wanted, workspace, [obstacle]);
console.assert(answer.x === 1.75 && answer.y === 1);
console.assert(wanted.x === 3);

const result = {
  declared: 119, passed: 98, skipped: 21,
  failed: 0, unrun: 0
};
const accounted = result.passed + result.skipped
  + result.failed + result.unrun;
console.assert(accounted === result.declared);
console.log(`${result.passed} passed; ` +
  `${result.skipped} excluded; ${result.unrun} unrun`);

const oldPose = [5, 5.1, 8];
const newPose = [-2, 5.1, -8];
const delta = newPose.map((v, i) => v - oldPose[i]);
const length = Math.hypot(delta[0], delta[2]);
console.assert(delta[1] === 0);
console.log({ delta, length });

const metersPerUnit = .017;
const radius = .09 * 1.1;
const rim = radius - .0005;
const diameter = 2 * radius / metersPerUnit;
console.assert(Math.abs(rim - .0985) < 1e-12);
console.log({ radius, rim, diameter });

